/* Finite State Machine for Alarm Subsystem */
states {
    Idle;
    HighLeakageAlarm;
    InvoluntaryShutdownAlarm;
    ACMainLossAlarm;
}

events {
    LeakageMeasured;
    ACMainLossDetected;
    ACMainRestored;
    AlarmTimeout;
}

transitions {
    Idle --> HighLeakageAlarm : LeakageMeasured[gauge(AverageLeakage > 3 L/min)];
    HighLeakageAlarm --> Idle : AlarmTimeout;
    Idle --> InvoluntaryShutdownAlarm : ACMainLossDetected;
    InvoluntaryShutdownAlarm --> Idle : ACMainRestored;
    InvoluntaryShutdownAlarm --> InvoluntaryShutdownAlarm : AlarmTimeout[true]; // continuous for at least 2 min
    Idle --> ACMainLossAlarm : ACMainLossDetected;
    ACMainLossAlarm --> Idle : ACMainRestored;
}

initial state Idle;

/* Guards */
gauge(AverageLeakage > 3 L/min) {
    // Average leakage over X seconds > 3 L/min
    return measuredLeakageAverage > 3;
}

/* Priority handling is implicit via state ordering and event handling */
